// Independent mathematical controls only. Does not read physical/model measurements.
package main
import("crypto/sha256";"encoding/binary";"encoding/json";"fmt";"math";"math/cmplx";"math/rand";"os";"path/filepath";"testing")
type qualification struct{output string;rows []map[string]interface{};errors []string;resolved int;unresolved int}
func TestGenericCommonHistory(t *testing.T){
 output:=filepath.Join(history_test_dir(t),"generic")
 job:=qualification{output:output}
 e:=job.run();if e!=nil{t.Fatal(e)}
 data,e:=os.ReadFile(filepath.Join(output,"qualification.json"));if e!=nil{t.Fatal(e)}
 var report struct{Records int `json:"records"`;Errors []string `json:"method_errors"`;Supported int `json:"grid_supported"`;Unresolved int `json:"grid_unresolved_retained"`}
 e=json.Unmarshal(data,&report);if e!=nil{t.Fatal(e)}
 if report.Records!=1323||len(report.Errors)!=0||report.Supported!=648||report.Unresolved!=567{t.Fatal("original generic qualification shape changed")}
}
func(j *qualification)run()error{e:=os.Mkdir(j.output,0755);if e!=nil{return e};j.rows=[]map[string]interface{}{};j.errors=[]string{};markers:=[2]interval{{2304,3328},{8192,9216}};for _,family:=range[]string{"aligned","seeded-independent","four-clusters","paired-near-cancel","exact-cancel"}{for _,phase:=range[]float64{0,.7,2.2}{for _,a:=range[]float64{64,128,512}{for _,q:=range[]float64{1,4,7}{for _,g:=range[]float64{.5,1,3}{for _,dc:=range[]float64{-13,0,7}{low:=ensemble(family,a,phase);left,right:=signal(low,low*complex(g,0),q,dc,markers,"");r,e:=observe(left,right,10368,q,false);name:=fmt.Sprintf("grid-%s-%g-%g-%g-%g-%g",family,phase,a,q,g,dc);row:=map[string]interface{}{"name":name,"kind":"generic_common_scaling","family":family,"global_phase":phase,"individual_amplitude":a,"known_quantizer_q":q,"generic_middle_scalar":g,"dc":dc,"result":r,"right_sha256":signal_hash(right),"left_sha256":signal_hash(left)};if e!=nil{j.errors=append(j.errors,name+":"+e.Error())}else if r.State=="supported_generic_low_reference"{j.resolved++;if !r.HoldOK||!r.ReturnOK{j.errors=append(j.errors,name+":common held prediction failed")};truth:=[3]float64{imag(low),real(low),dc};for k:=0;k<3;k++{if math.Abs(r.Low.Beta[k]-truth[k])>r.Low.Bound[k]+1e-6{j.errors=append(j.errors,name+":true coefficient outside known synthetic bound")}}}else{j.unresolved++;row["unresolved_guard_retained"]=true};j.rows=append(j.rows,row)}}}}}};j.calibrations(markers);j.failures(markers);report:=map[string]interface{}{"state":"finite_generic_commonhistory_qualification_complete","grid_records":1215,"grid_supported":j.resolved,"grid_unresolved_retained":j.unresolved,"records":len(j.rows),"method_errors":j.errors,"observations":j.rows,"limits":[]string{"No models/hardware/data-dependent tolerance; known uniform-round q bounds apply ONLY to these mathematical controls","Scalar aggregate agreement does not establish identical per-voice response or TL0 extrapolation","Aggregate overload middle is never phase/gain/DC fitted; arbitrary clipping/wrapping examples are not a chip oracle","Marker256/guard128/interior1536/train1024/holdout512 remain unchanged"}};raw,e:=json.MarshalIndent(report,"","  ");if e!=nil{return e};e=exclusive(filepath.Join(j.output,"qualification.json"),append(raw,'\n'));if e!=nil{return e};if len(j.errors)>0{return fmt.Errorf("%d method errors retained",len(j.errors))};fmt.Printf("Generic grid1215: supported%d unresolved%d; total%d; no method errors\n",j.resolved,j.unresolved,len(j.rows));return nil}
func ensemble(family string,a,phase float64)complex128{z:=complex(0.,0.);rng:=rand.New(rand.NewSource(219));for k:=0;k<32;k++{p:=phase;switch family{case"seeded-independent":p+=rng.Float64()*2*math.Pi;case"four-clusters":p+=[]float64{0,.1,1.1,2.4}[k%4];case"paired-near-cancel":if k%2==1{p+=math.Pi+.001};case"exact-cancel":if k%2==1{p+=math.Pi}};z+=cmplx.Rect(a,p)};return z}
func signal(low,mid complex128,q,dc float64,markers [2]interval,injection string)([]float64,[]float64){left,right:=make([]float64,16384),make([]float64,16384);rotation:=cmplx.Rect(1,native_w);z,zmid:=low,mid;drift:=complex(1.,0.);for n:=range right{value:=imag(z);if n>=markers[0].First&&n<markers[1].End{value=imag(zmid)};if n>=markers[1].End{switch injection{case"return_phase":value=imag(z*cmplx.Rect(1,.04));case"return_gain":value=imag(z)*1.05;case"return_dc":value+=18}};if injection=="frequency_drift"&&n>=markers[0].End{drift*=cmplx.Rect(1,2*math.Pi*.5/(1<<20));if n>=markers[1].End{value=imag(z*drift)}};if injection=="stage_inside"{for k,m:=range markers{if n>=m.First&&n<m.End{fraction:=float64(1+32*(n-m.First)/(m.End-m.First))/32;if k==0{value=imag(z)*(1-fraction)+imag(zmid)*fraction}else{value=imag(zmid)*(1-fraction)+imag(z)*fraction};value+=123*math.Sin(float64(n))*fraction*(1-fraction)}}};if injection=="late_stage"&&n>=markers[0].End+128&&n<markers[0].End+128+1024{value*=1.1};if injection=="clip_middle"&&n>=markers[0].End&&n<markers[1].First{value=math.Max(-4703,math.Min(4703,value))};if injection=="wrap_middle"&&n>=markers[0].End&&n<markers[1].First{value=math.Mod(value+6007,12014);if value<0{value+=12014};value-=6007};value=math.Max(-20003,math.Min(20003,value));right[n]=q*math.Round((dc+value)/q);left[n]=right[n];for _,m:=range markers{if n>=m.First&&n<m.End{left[n]=0}};z*=rotation;zmid*=rotation};return left,right}
func(j *qualification)calibrations(markers [2]interval){for _,phase:=range[]float64{0,.7,2.2}{for _,a:=range[]float64{64,128,512}{for _,q:=range[]float64{1,4,7}{single:=cmplx.Rect(a,phase);l1,r1:=signal(single,single*.5,q,7,markers,"");s,e:=observe(l1,r1,10368,q,true);if e!=nil{j.errors=append(j.errors,e.Error());continue};g,lo,hi,ok:=gain_interval(s);for _,family:=range[]string{"aligned","seeded-independent","four-clusters"}{low:=ensemble(family,a,phase);l2,r2:=signal(low,low*.5,q,7,markers,"");agg,e:=observe(l2,r2,10368,q,true);ratio,closes:=scalar_closure(agg,g,lo,hi);_,_,_,aggregate_supported:=gain_interval(agg);evaluated:=ok&&aggregate_supported;row:=map[string]interface{}{"name":"paired-low-gain","family":family,"phase":phase,"amplitude":a,"known_q":q,"single":s,"aggregate":agg,"N1_gain":g,"N1_gain_interval":[]float64{lo,hi},"N1_calibration_supported":ok,"aggregate_scalar_error_ratio":ratio,"aggregate_closure_consistent":evaluated&&closes,"aggregate_scalar_check_evaluated":evaluated,"uniform_all32_response_proved":false};if e!=nil{j.errors=append(j.errors,e.Error())};if !evaluated{row["aggregate_closure_consistent"]=nil;row["aggregate_scalar_check_state"]="unresolved_input_support"}else{row["aggregate_scalar_check_state"]="evaluated"};if evaluated&&!closes{j.errors=append(j.errors,"common low-gain scalar mismatch")};j.rows=append(j.rows,row)}}}};low:=ensemble("aligned",512,.7);single:=cmplx.Rect(512,.7);l1,r1:=signal(single,single*.5,1,7,markers,"");s,_:=observe(l1,r1,10368,1,true);g,lo,hi,_:=gain_interval(s);for _,item:=range[]struct{name string;mid complex128;detect bool}{{"noncommon_detectable_gain",noncommon_mid("gain"),true},{"noncommon_but_same_aggregate",noncommon_mid("hidden"),false},{"noncommon_detectable_phase",noncommon_mid("phase"),true}}{l,r:=signal(low,item.mid,1,7,markers,"");o,e:=observe(l,r,10368,1,true);ratio,ok:=scalar_closure(o,g,lo,hi);j.rows=append(j.rows,map[string]interface{}{"name":item.name,"underlying_pervoice_gain_description":"M1 staysgain0.5; hidden other15gain0.25/other15gain0.75/finalgain0.5 averages0.5; gain/phase counterexamples have independently weighted contributions","result":o,"scalar_error_ratio":ratio,"aggregate_closure_consistent":ok,"uniform_pervoice_response_proved":false,"identifiability_limit_retained":!item.detect});if e!=nil||ok==item.detect{j.errors=append(j.errors,item.name+":wrong finite observability state")}}}
func(j *qualification)failures(markers [2]interval){low:=ensemble("aligned",128,.7);for _,inj:=range[]string{"return_phase","return_gain","return_dc","frequency_drift","late_stage","stage_inside","clip_middle","wrap_middle"}{gain:=1.;if inj=="clip_middle"||inj=="wrap_middle"{gain=3};l,r:=signal(low,low*complex(gain,0),1,7,markers,inj);middle:=inj=="late_stage"||inj=="stage_inside";o,e:=observe(l,r,10368,1,middle);expected:=true;if inj=="late_stage"{expected=o.MiddleState=="middle_unstable"}else if inj=="stage_inside"{expected=o.ReturnOK&&o.HoldOK&&o.MiddleState=="fixed_frequency_middle_holdout_consistent"}else if inj!="clip_middle"&&inj!="wrap_middle"{expected=!o.ReturnOK};if e!=nil||!expected{j.errors=append(j.errors,inj+":strong injection not retained/detected")};j.rows=append(j.rows,map[string]interface{}{"name":inj,"kind":"failure_or_distorted_middle_retained","result":o,"expected_method_behavior":expected,"no_mechanism_classification":true});j.save_curve(inj,l,r,o)};duration:=[]struct{name string;markers [2]interval;final int;state string}{{"marker255",[2]interval{{2304,2559},markers[1]},10368,"unqualified_marker_count"},{"marker256",[2]interval{{2304,2560},markers[1]},10368,"supported_generic_low_reference"},{"pre1535",[2]interval{{1791,2815},markers[1]},10368,"unqualified_short_interiors"},{"pre1536",[2]interval{{1792,2816},markers[1]},10368,"supported_generic_low_reference"},{"middle1535",[2]interval{markers[0],{5119,6143}},10368,"unqualified_short_interiors"},{"middle1536",[2]interval{markers[0],{5120,6144}},10368,"supported_generic_low_reference"},{"return1535",markers,14849,"unqualified_short_interiors"},{"return1536",markers,14848,"supported_generic_low_reference"}};for _,item:=range duration{l,r:=signal(low,low,1,7,item.markers,"");o,e:=observe(l,r,item.final,1,true);if e!=nil||o.State!=item.state{j.errors=append(j.errors,item.name+":wrong boundary state")};j.rows=append(j.rows,map[string]interface{}{"name":item.name,"kind":"duration_guard","expected_state":item.state,"result":o})};for _,name:=range[]string{"missing_marker","extra_marker"}{l,r:=signal(low,low,1,7,markers,"");if name=="missing_marker"{for n:=markers[0].First;n<markers[0].End;n++{l[n]=r[n]}}else{for n:=12000;n<12300;n++{l[n]=0}};o,e:=observe(l,r,10368,1,true);if e!=nil||o.State!="unqualified_marker_count"{j.errors=append(j.errors,name+":not rejected")};j.rows=append(j.rows,map[string]interface{}{"name":name,"result":o})};for _,name:=range[]string{"nonfinite","fractional","out_of_range","different_lengths","late_final_bound","bad_q"}{l,r:=signal(low,low,1,7,markers,"");final,q:=10368,1.;switch name{case"nonfinite":r[8]=math.NaN();case"fractional":r[8]=.5;case"out_of_range":r[8]=32768;case"different_lengths":l=l[:100];case"late_final_bound":final=16385;case"bad_q":q=0};_,e:=observe(l,r,final,q,true);if e==nil{j.errors=append(j.errors,name+":invalid array accepted")};message:="";if e!=nil{message=e.Error()};j.rows=append(j.rows,map[string]interface{}{"name":name,"kind":"invalid_input_rejected","error":message})}}
func(j *qualification)save_curve(name string,left,right []float64,o observed){data:=[]byte("sample,left,right,prediction_from_early_low\n");for n:=range right{prediction:="";if o.Low!=nil{x:=basis(n);p:=0.;for k:=0;k<3;k++{p+=x[k]*o.Low.Beta[k]};prediction=fmt.Sprintf("%.9f",p)};data=append(data,[]byte(fmt.Sprintf("%d,%.0f,%.0f,%s\n",n,left[n],right[n],prediction))...)};if e:=exclusive(filepath.Join(j.output,name+".csv"),data);e!=nil{j.errors=append(j.errors,e.Error())}}
func signal_hash(v []float64)string{b:=make([]byte,len(v)*2);for n,x:=range v{binary.LittleEndian.PutUint16(b[n*2:],uint16(int16(x)))};return fmt.Sprintf("%x",sha256.Sum256(b))}
func exclusive(path string,data []byte)error{f,e:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return e};_,e=f.Write(data);ce:=f.Close();if e!=nil{return e};return ce}

func noncommon_mid(kind string)complex128{z:=complex(0.,0.);for k:=0;k<32;k++{g,phase:=.5,.7;switch kind{case"gain":if k>=16{g=1};case"hidden":if k>=1&&k<=15{g=.25}else if k>=16&&k<=30{g=.75};case"phase":if k>=16{phase+=.08}};z+=cmplx.Rect(512*g,phase)};return z}
